from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

# Set up all devices.
prime_hub = PrimeHub()
color_sensor = ColorSensor(Port.C)
right_attachment = Motor(Port.D, Direction.CLOCKWISE)
left_attachment_ = Motor(Port.A, Direction.COUNTERCLOCKWISE)
left_wheel = Motor(Port.E, Direction.COUNTERCLOCKWISE)
right_wheel = Motor(Port.F, Direction.CLOCKWISE)
drive_base = DriveBase(left_wheel, right_wheel, 88.9, 112)

async def main():
    await multitask(
        left_attachment_.run_until_stalled(-500, Stop.HOLD, 50),
        right_attachment.run_until_stalled(-500, Stop.HOLD, 50),
        race=True,
    )
    drive_base.use_gyro(True)
    drive_base.settings(straight_speed=400)
    drive_base.settings(turn_rate=100)
    await drive_base.straight(550, then=Stop.NONE)
    while True:
        await wait(0)
        if await color_sensor.reflection() <= 20:
            drive_base.straight(0)
            break
        else:
            drive_base.drive(100, 0)
    await drive_base.straight(-20)
    await drive_base.turn(-30)
    drive_base.settings(turn_rate=75)
    await drive_base.straight(40)
    await drive_base.turn(-50)
    await drive_base.straight(-25)
    await drive_base.straight(240)
    await drive_base.turn(-30)
    await drive_base.straight(25)
    await left_attachment_.run_angle(250, 175)
    await drive_base.straight(15)
    await drive_base.turn(25)
    await drive_base.straight(90)
    await drive_base.turn(28)
    await drive_base.straight(-170)
    await drive_base.straight(100)


run_task(main())